    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_bids = []
    moderate_bids = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 60:
                    aggressive_bids.append(bid)
                else:
                    moderate_bids.append(bid)

    alive_count = len(alive)
    if alive_count == 0:
        return min(budget, 18.0)

    units = int(supply / WATER_REQ)
    scarce = units <= 1
    tight = alive_count > units

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    highest_moderate = max(moderate_bids) if moderate_bids else 0.0
    highest_aggressive = max(aggressive_bids) if aggressive_bids else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if scarce:
        danger += 2
    elif tight:
        danger += 1

    if budget <= 0:
        return 0.0

    if danger >= 4:
        target = max(66.0, highest_prev + 1.2)
    elif danger >= 3:
        target = max(58.0, highest_moderate + 2.0)
        if highest_aggressive > 0:
            target = max(target, min(highest_aggressive + 0.8, 69.0))
    elif scarce:
        target = max(52.0, highest_moderate + 1.5)
        if highest_aggressive >= 68:
            target = min(64.0, budget)
    else:
        if units >= 2:
            target = 24.0
            if avg_prev > 55:
                target = 19.0
            elif highest_moderate > 0:
                target = min(34.0, highest_moderate + 1.0)
        else:
            target = 42.0

    if budget < DAILY_SALARY * 0.6 and danger <= 2:
        target = min(target, 38.0)

    if hp >= 8 and no_water_days == 0 and not scarce:
        target = min(target, 28.0)

    target = max(0.0, min(float(target), float(budget)))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # Base bid: Start with a moderate bid, e.g., 50% of daily salary
    bid_value = DAILY_SALARY * 0.5

    # --- HP-based adjustment ---
    # If HP is critical, bid very aggressively
    if my_status['hp'] <= 2:
        bid_value = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4 and my_status['no_water_days'] > 0:
        bid_value = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 4:
        bid_value = DAILY_SALARY * 0.75

    # --- Opponent-based adjustment using previous_trace ---
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If highest previous bid was very high, respond aggressively
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 4:
                bid_value = max(bid_value, highest_prev_bid * 0.95) # Try to get it slightly cheaper if possible
            else:
                bid_value = max(bid_value, highest_prev_bid + (DAILY_SALARY * 0.05)) # Bid slightly above

        # If highest previous bid was moderately high
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid_value = max(bid_value, highest_prev_bid + (DAILY_SALARY * 0.02)) # Bid slightly above

        # If highest previous bid was low, try to win cheaply
        else:
            bid_value = max(bid_value, highest_prev_bid + (DAILY_SALARY * 0.01)) # Just slightly above

    # --- Supply-based adjustment ---
    # Estimate total water needed by all alive agents (including myself)
    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    # If supply is scarce compared to total demand, increase bid
    if day_context['supply'] < total_water_needed:
        scarcity_factor = (total_water_needed / day_context['supply'])
        bid_value *= min(1.3, scarcity_factor * 0.7)

    # --- Day-based adjustment (later days are more critical) ---
    if day_context['day'] > EPISODE_DAYS * 0.7:
        bid_value *= 1.05

    # --- Final constraints ---
    final_bid = min(bid_value, my_status['budget'])

    if my_status['budget'] > 0 and final_bid < DAILY_SALARY * 0.1:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    final_bid = max(0.0, final_bid)

    return round(final_bid, 2)
